// 1. Get raw HTML from the previous HTTP Request node
const html = $input.first().json.data; 

// 2. Extract all hidden <app-data> blocks
const regex = /<app-data[^>]*>(.*?)<\/app-data>/g;
const matches = [...html.matchAll(regex)];

let selectedPublication = null;
const now = new Date();

for (const match of matches) {
  try {
    // Convert HTML entity quotes (&quot;) back to standard quotes (")
    const cleanJson = match[1].replace(/&quot;/g, '"');
    const data = JSON.parse(cleanJson);

    // Locate the block containing the publications array
    if (Array.isArray(data) && data[0] && Array.isArray(data[0].publications)) {
      const publications = data[0].publications;

      // Filter for flyers that are currently active right now
      const activePublications = publications.filter(p => {
        const from = new Date(p.validFrom);
        const until = new Date(p.validUntil);
        return from <= now && until >= now;
      });

      if (activePublications.length > 0) {
        // Prioritize the weekly flyer (typically labeled 'Uge X')
        const weeklyGroceryFlyer = activePublications.find(p => 
          p.label && p.label.toLowerCase().includes('uge')
        );

        // Fall back to the first active circular if 'Uge' isn't explicitly in the title
        selectedPublication = weeklyGroceryFlyer || activePublications[0];
        break; 
      }
    }
  } catch (e) {
    // Skip blocks that fail JSON parsing
  }
}

if (!selectedPublication) {
  throw new Error("No active weekly grocery flyer found for this store.");
}

// 3. Return the publication details for downstream nodes
return [{
  json: {
    publicationId: selectedPublication.id,
    label: selectedPublication.label,
    validFrom: selectedPublication.validFrom,
    validUntil: selectedPublication.validUntil
  }
}];

// 1. Get the raw HTML from the previous HTTP Request
const html = $input.first().json.data; 

// 2. Find all hidden <app-data> blocks
const regex = /<app-data[^>]*>(.*?)<\/app-data>/g;
const matches = [...html.matchAll(regex)];

let flyerPages = [];

for (const match of matches) {
  try {
    // 3. Clean the HTML formatting back to standard JSON
    const cleanJson = match[1].replace(/&quot;/g, '"');
    const data = JSON.parse(cleanJson);

    // 4. Look for the specific block holding the publication images
    if (data.publication && data.publication.images) {
      // Extract the URL and fix HTML entities (&amp; -> &)
      flyerPages = data.publication.images.map(img => img.url.replace(/&amp;/g, '&'));
      break; 
    }
  } catch (e) {
    // Ignore invalid JSON blocks
  }
}

if (flyerPages.length === 0) {
  throw new Error("Could not find image URLs in the HTML.");
}

// 5. Output each URL as a separate item for the loop
return flyerPages.map(url => ({
  json: { 
    imageUrl: url 
  }
}));

// 1. Grab all the aggregated items coming out of the Loop's 'done' branch
const allItems = $input.all();
const flattenedItems = [];

// Safely get the store name without crashing if the path is undefined
let defaultStore = "$('AISubWorkFlow').first().json.Store"

for (const item of allItems) {
  let rawText = item.json.text;

  // Skip if there's no text output
  if (!rawText) continue;

  try {
    // 2. Strip out the ```json and ``` wrappers so it is pure JSON data
    let cleanedText = rawText
      .replace(/```json/gi, '')
      .replace(/```/g, '')
      .trim();

    // 3. Parse the clean string back into a JavaScript array
    const parsed = JSON.parse(cleanedText);

    // 4. If the array has items, push them into our master list
    if (Array.isArray(parsed) && parsed.length > 0) {
      flattenedItems.push(...parsed);
    }
  } catch (e) {
    // Skip this specific page if the JSON is somehow malformed
  }
}

// 5. Output each deal as its own individual item for the database
return flattenedItems.map(item => ({
  json: {
    item_name_dk: item.item_name_dk,
    item_name_en: item.item_name_en,
    category: item.category,
    price: Number(item.price),
    unit: item.unit,
    // Clean up empty or 'Unknown' store names generated by the AI
    store: (item.store && item.store !== "Unknown" && item.store !== "") 
           ? item.store 
           : defaultStore,
    extracted_at: new Date().toISOString()
  }
}));

// Add this code node between ExtractStores and LoopOverStores
const stores = $input.first().json.data.stores;
return stores.map(s => ({ json: { store: s.store } }));

