-- Create an empty staging table for the new harvest run
DROP TABLE IF EXISTS "GroceryDeals_Staging";
CREATE TABLE "GroceryDeals_Staging" (LIKE "GroceryDeals_Latest" INCLUDING ALL);

BEGIN;

-- 1. Rename the currently active table to an archive table with the timestamp
--ALTER TABLE IF EXISTS "GroceryDeals_Latest" 
--RENAME TO "GroceryDeals_Latest_{{ $now.toFormat('yyyy_MM_dd_HH') }}";

-- 2. Promote the staging table to become the new live table
--ALTER TABLE IF EXISTS "GroceryDeals_Staging" 
--RENAME TO "GroceryDeals_Latest";

DO $$ 
DECLARE 
    target_table record;
    table_date timestamp;
BEGIN 
    -- Loop through all tables that start with the archive prefix
    FOR target_table IN 
        SELECT table_name 
        FROM information_schema.tables 
        WHERE table_schema = 'public' 
          AND table_name LIKE 'GroceryDeals_Latest_20%' 
    LOOP 
        BEGIN
            -- Extract timestamp starting at char 21 with matching format YYYY_MM_DD_HH24
            table_date := to_timestamp(substring(target_table.table_name from 21), 'YYYY_MM_DD_HH24');

            -- Drop if older than 14 days
            IF table_date < (NOW() - INTERVAL '14 days') THEN 
                EXECUTE 'DROP TABLE IF EXISTS "' || target_table.table_name || '";'; 
            END IF;

        EXCEPTION WHEN OTHERS THEN
            -- Skip if date parsing encounters an unexpected naming variation
            CONTINUE;
        END;
    END LOOP; 
END $$;

